// Package automation manages automation tokens: bearer credentials for the management API used by Terraform and
// scripts (ADR-0041). A token acts for the user who created it, restricted either to an installation role or to one
// tenant and a set of tenant permissions. Tokens are generated by Porch, shown once, stored as HMACs under the keyring
// token key, and expire, except installation tokens an installation owner issues without expiry (ADR-0046). A token
// may issue narrower tokens that never outlive it; revoking a token revokes everything it issued (ADR-0048).
package automation

import (
	"context"
	"crypto/hmac"
	"database/sql"
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"time"

	"github.com/aurimasniekis/go-porch/internal/apperr"
	"github.com/aurimasniekis/go-porch/internal/audit"
	"github.com/aurimasniekis/go-porch/internal/authz"
	"github.com/aurimasniekis/go-porch/internal/clock"
	"github.com/aurimasniekis/go-porch/internal/domain"
	"github.com/aurimasniekis/go-porch/internal/ids"
	"github.com/aurimasniekis/go-porch/internal/keyring"
	"github.com/aurimasniekis/go-porch/internal/session"
	"github.com/aurimasniekis/go-porch/internal/store"
	"github.com/aurimasniekis/go-porch/internal/store/db"
)

// Prefix marks automation tokens (secret scanners can match it).
const Prefix = "porch_at_"

// MaxLifetime bounds a token's validity.
const MaxLifetime = 366 * 24 * time.Hour

// neverExpiresAt is the expires_at stored for tokens without expiry, so every expiry comparison and the cleanup of
// expired tokens hold unchanged.
var neverExpiresAt = time.Date(9999, 12, 31, 0, 0, 0, 0, time.UTC)

const macDomain = "porch/automation-token/v1|"

// Kinds of tokens.
const (
	KindInstallation = "installation"
	KindTenant       = "tenant"
)

// Installation token roles.
const (
	RoleAdmin     = "admin"
	RoleAuditor   = "auditor"
	RoleInspector = "inspector"
)

// maxChain bounds how many tokens deep issuance may go, so walking a token's issuers stays cheap.
const maxChain = 8

// ErrInvalid is returned for unknown, expired or revoked tokens (deliberately indistinguishable).
var ErrInvalid = apperr.New(apperr.CodeUnauthorized, "invalid automation token")

// ErrNotFound is returned for unknown token IDs.
var ErrNotFound = apperr.New(apperr.CodeNotFound, "automation token not found")

// Token describes a token (never the secret).
type Token struct {
	ID          string     `json:"id"`
	Name        string     `json:"name"`
	Kind        string     `json:"kind" enum:"installation,tenant"`
	TenantID    string     `json:"tenant_id,omitempty"`
	Role        string     `json:"role,omitempty" enum:"admin,auditor,inspector,"`
	Permissions []string   `json:"permissions"`
	Hint        string     `json:"hint" doc:"Last characters of the token."`
	CreatedBy   string     `json:"created_by"`
	CreatorName string     `json:"creator_name,omitempty"`
	CreatedAt   time.Time  `json:"created_at"`
	ExpiresAt   *time.Time `json:"expires_at,omitempty" doc:"Absent when the token never expires."`
	// NeverExpires marks an installation token issued by an owner without expiry (ADR-0046). It also keeps working
	// without the identity provider's periodic confirmation of its creator.
	NeverExpires bool `json:"never_expires"`
	// IssuedBy is the automation token that issued this one; absent when a person did.
	IssuedBy   string     `json:"issued_by,omitempty" doc:"The automation token that issued this one (absent when a person did). Revoking it revokes this token."`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	LastUsedIP string     `json:"last_used_ip,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

func fromRow(r db.AutomationToken, creator string) Token {
	var perms []string
	_ = json.Unmarshal([]byte(r.Permissions), &perms)
	if perms == nil {
		perms = []string{}
	}
	t := Token{ID: r.ID, Name: r.Name, Kind: r.Kind, TenantID: r.TenantID.String, Role: r.Role.String, Permissions: perms, Hint: r.Hint,
		CreatedBy: r.CreatedBy, CreatorName: creator, CreatedAt: domain.FromMicros(r.CreatedAt), NeverExpires: r.NeverExpires == 1,
		IssuedBy: r.IssuedBy.String, LastUsedAt: domain.OptMicros(r.LastUsedAt), LastUsedIP: r.LastUsedIp, RevokedAt: domain.OptMicros(r.RevokedAt)}
	if !t.NeverExpires {
		exp := domain.FromMicros(r.ExpiresAt)
		t.ExpiresAt = &exp
	}
	return t
}

// Service manages automation tokens.
type Service struct {
	s     *store.Store
	kr    *keyring.Keyring
	audit *audit.Writer
	clock clock.Clock
}

// New returns the service.
func New(s *store.Store, kr *keyring.Keyring, a *audit.Writer, c clock.Clock) *Service {
	return &Service{s: s, kr: kr, audit: a, clock: c}
}

// CreateParams describe a new token. The caller has already checked that the creator may hold what the token grants.
type CreateParams struct {
	Name        string
	Kind        string
	TenantID    string
	Role        string
	Permissions []string
	Lifetime    time.Duration
	// NeverExpires issues an installation token without expiry (Lifetime must be 0). The API allows it only to
	// installation owners.
	NeverExpires bool
	CreatedBy    string
	// Issuer is the automation token issuing this one, nil when a person does. The caller has already checked that the
	// issuer's creator may issue tokens at all; Create enforces that the new token is no broader than the issuer and
	// does not outlive it.
	Issuer *session.TokenGrant
}

// covers reports whether an installation token role includes another: admin includes every role, the read-only
// roles only themselves.
func covers(have, want string) bool { return have == RoleAdmin || have == want }

// ReadOnly reports whether a token grant only reads: an auditor or inspector installation token, or a tenant token
// whose permissions all have the action "read". Read-only tokens never issue tokens (ADR-0048).
func ReadOnly(g *session.TokenGrant) bool {
	if g.TenantID == "" {
		return g.Role != RoleAdmin
	}
	return !slices.ContainsFunc(g.Permissions, func(p string) bool {
		_, action, _ := strings.Cut(p, ":")
		return action != "read"
	})
}

// checkIssuer validates p against the token issuing it.
func checkIssuer(p CreateParams, now time.Time, v *apperr.Validation) {
	is := p.Issuer
	switch {
	case ReadOnly(is):
		v.Add("kind", "a read-only token cannot issue tokens")
	case is.TenantID == "" && p.Kind == KindInstallation:
		if !covers(is.Role, p.Role) {
			v.Add("role", "an %s token cannot issue %s tokens", is.Role, p.Role)
		}
	case is.TenantID == "" && p.Kind == KindTenant:
		if is.Role != RoleAdmin {
			v.Add("kind", "only admin installation tokens can issue tenant tokens")
		}
	case p.Kind == KindTenant && is.TenantID == p.TenantID:
		for _, perm := range p.Permissions {
			if !slices.ContainsFunc(is.Permissions, func(have string) bool { return authz.Grants(have, perm) }) {
				v.Add("permissions", "the issuing token does not hold %s", perm)
			}
		}
	default:
		v.Add("kind", "a tenant token can only issue tokens for its own tenant")
	}
	switch {
	case p.NeverExpires && !is.NeverExpires:
		v.Add("never_expires", "only a token that never expires can issue one")
	case !p.NeverExpires && !is.NeverExpires && now.Add(p.Lifetime).After(is.ExpiresAt):
		v.Add("expires_in_days", "must not outlive the issuing token (it expires %s)", is.ExpiresAt.UTC().Format(time.RFC3339))
	}
}

// Create issues a token and returns it with its secret (shown once).
func (svc *Service) Create(ctx context.Context, ch domain.Change, p CreateParams) (Token, string, error) {
	var v apperr.Validation
	p.Name = domain.CleanName("name", p.Name, &v)
	switch {
	case p.NeverExpires && p.Kind != KindInstallation:
		v.Add("never_expires", "only installation tokens can be issued without expiry")
	case p.NeverExpires && p.Lifetime != 0:
		v.Add("expires_in_days", "must be omitted for a token that never expires")
	case !p.NeverExpires && (p.Lifetime <= 0 || p.Lifetime > MaxLifetime):
		v.Add("expires_in_days", "must be between 1 and 366 days")
	}
	switch p.Kind {
	case KindInstallation:
		if p.Role != RoleAdmin && p.Role != RoleAuditor && p.Role != RoleInspector {
			v.Add("role", "must be admin, auditor or inspector")
		}
		p.TenantID, p.Permissions = "", nil
	case KindTenant:
		if p.TenantID == "" {
			v.Add("tenant", "required")
		}
		if len(p.Permissions) == 0 || len(p.Permissions) > 50 {
			v.Add("permissions", "1 to 50 permissions")
		}
		p.Role = ""
	default:
		v.Add("kind", "must be installation or tenant")
	}
	if p.Issuer != nil {
		checkIssuer(p, svc.clock.Now(), &v)
	}
	if err := v.Err(); err != nil {
		return Token{}, "", err
	}
	r, err := session.RandomToken()
	if err != nil {
		return Token{}, "", err
	}
	secret := Prefix + r
	mac, err := svc.kr.MAC(keyring.PurposeToken, []byte(macDomain+secret))
	if err != nil {
		return Token{}, "", err
	}
	perms := slices.Clone(p.Permissions)
	slices.Sort(perms)
	perms = slices.Compact(perms)
	if perms == nil {
		perms = []string{}
	}
	pj, _ := json.Marshal(perms)
	id := ids.New(ids.AutomationToken)
	var issuedBy string
	if p.Issuer != nil {
		issuedBy = p.Issuer.ID
		chain, err := svc.issuers(ctx, issuedBy)
		if err != nil {
			return Token{}, "", err
		}
		if len(chain)+1 >= maxChain {
			return Token{}, "", apperr.New(apperr.CodeInvalid, "tokens can be issued at most %d tokens deep", maxChain)
		}
	}
	err = svc.s.W().TxNamed(ctx, "automation.create", func(tx *store.Tx) error {
		expires, never, expiry := tx.Now.Add(p.Lifetime), int64(0), tx.Now.Add(p.Lifetime).UTC().Format(time.RFC3339)
		if p.NeverExpires {
			expires, never, expiry = neverExpiresAt, 1, "never"
		}
		if err := tx.Q.InsertAutomationToken(ctx, db.InsertAutomationTokenParams{ID: id, Mac: mac, Hint: secret[len(secret)-4:], Name: p.Name,
			Kind: p.Kind, TenantID: domain.NullStr(p.TenantID), Role: domain.NullStr(p.Role), Permissions: string(pj), CreatedBy: p.CreatedBy,
			CreatedAt: tx.NowMicros(), ExpiresAt: expires.UnixMicro(), NeverExpires: never, IssuedBy: domain.NullStr(issuedBy)}); err != nil {
			return err
		}
		details := map[string]any{"kind": p.Kind, "role": p.Role, "permissions": perms, "expires_at": expiry, "never_expires": p.NeverExpires}
		if issuedBy != "" {
			details["issued_by"] = issuedBy
		}
		_, err := svc.audit.Append(ctx, tx, audit.Event{Actor: ch.Actor, TenantID: p.TenantID, Action: "automation_token.created",
			Target: audit.Target{Type: "automation_token", ID: id}, Details: details})
		return err
	})
	if err != nil {
		return Token{}, "", err
	}
	t, err := svc.Get(ctx, id)
	return t, secret, err
}

// Authenticate resolves a presented token. Unknown, expired and revoked tokens fail alike. Use is recorded at most
// once a minute.
func (svc *Service) Authenticate(ctx context.Context, raw, ip string) (*session.TokenGrant, string, error) {
	if !strings.HasPrefix(raw, Prefix) || len(raw) > 128 {
		return nil, "", ErrInvalid
	}
	macs, err := svc.kr.MACAll(keyring.PurposeToken, []byte(macDomain+raw))
	if err != nil {
		return nil, "", err
	}
	var row db.AutomationToken
	found := false
	for _, m := range macs {
		r, err := svc.s.R().GetAutomationTokenByMAC(ctx, m)
		if err == nil && hmac.Equal(r.Mac, m) {
			row, found = r, true
			break
		}
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return nil, "", err
		}
	}
	now := svc.clock.Now()
	if !found || row.RevokedAt.Valid || now.UnixMicro() >= row.ExpiresAt {
		return nil, "", ErrInvalid
	}
	if !row.LastUsedAt.Valid || now.Sub(domain.FromMicros(row.LastUsedAt.Int64)) > time.Minute || row.LastUsedIp != ip {
		_ = svc.s.W().TxNamed(ctx, "automation.touch", func(tx *store.Tx) error {
			return tx.Q.TouchAutomationToken(ctx, db.TouchAutomationTokenParams{LastUsedAt: domain.NullMicros(&tx.Now), LastUsedIp: ip, ID: row.ID})
		})
	}
	t := fromRow(row, "")
	return &session.TokenGrant{ID: t.ID, TenantID: t.TenantID, Role: t.Role, Permissions: t.Permissions, CreatedAt: t.CreatedAt,
		ExpiresAt: domain.FromMicros(row.ExpiresAt), NeverExpires: t.NeverExpires}, row.CreatedBy, nil
}

// Get returns one token.
func (svc *Service) Get(ctx context.Context, id string) (Token, error) {
	r, err := svc.s.R().GetAutomationToken(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return Token{}, ErrNotFound
	}
	if err != nil {
		return Token{}, err
	}
	return fromRow(r, ""), nil
}

// List returns the installation tokens (tenantID "") or the tokens of one tenant, newest first.
func (svc *Service) List(ctx context.Context, tenantID string) ([]Token, error) {
	var arg any
	if tenantID != "" {
		arg = tenantID
	}
	rows, err := svc.s.R().ListAutomationTokens(ctx, arg)
	if err != nil {
		return nil, err
	}
	out := make([]Token, 0, len(rows))
	for _, r := range rows {
		out = append(out, fromRow(db.AutomationToken{ID: r.ID, Mac: r.Mac, Hint: r.Hint, Name: r.Name, Kind: r.Kind, TenantID: r.TenantID, Role: r.Role,
			Permissions: r.Permissions, CreatedBy: r.CreatedBy, CreatedAt: r.CreatedAt, ExpiresAt: r.ExpiresAt, LastUsedAt: r.LastUsedAt,
			LastUsedIp: r.LastUsedIp, RevokedAt: r.RevokedAt, NeverExpires: r.NeverExpires, IssuedBy: r.IssuedBy}, r.CreatorName))
	}
	return out, nil
}

// issuers returns the tokens that issued id, nearest first (id itself excluded).
func (svc *Service) issuers(ctx context.Context, id string) ([]string, error) {
	var out []string
	for range maxChain {
		r, err := svc.s.R().GetAutomationToken(ctx, id)
		if errors.Is(err, sql.ErrNoRows) {
			return out, nil
		}
		if err != nil {
			return nil, err
		}
		if !r.IssuedBy.Valid {
			return out, nil
		}
		id = r.IssuedBy.String
		out = append(out, id)
	}
	return out, nil
}

// IssuedBy reports whether token id was issued, directly or through other tokens, by token issuer.
func (svc *Service) IssuedBy(ctx context.Context, id, issuer string) (bool, error) {
	chain, err := svc.issuers(ctx, id)
	return slices.Contains(chain, issuer), err
}

// Revoke ends a token immediately, with every token it issued (directly or through other tokens).
func (svc *Service) Revoke(ctx context.Context, ch domain.Change, id string) error {
	return svc.s.W().TxNamed(ctx, "automation.revoke", func(tx *store.Tx) error {
		r, err := tx.Q.GetAutomationToken(ctx, id)
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		n, err := tx.Q.RevokeAutomationToken(ctx, db.RevokeAutomationTokenParams{RevokedAt: domain.NullMicros(&tx.Now), ID: id})
		if err != nil {
			return err
		}
		if n == 0 {
			return apperr.New(apperr.CodeConflict, "token already revoked")
		}
		var issued []string
		next := []string{id}
		for depth := 0; len(next) > 0 && depth < maxChain; depth++ {
			var children []string
			for _, parent := range next {
				kids, err := tx.Q.ListAutomationTokensIssuedBy(ctx, domain.NullStr(parent))
				if err != nil {
					return err
				}
				children = append(children, kids...)
			}
			for _, c := range children {
				n, err := tx.Q.RevokeAutomationToken(ctx, db.RevokeAutomationTokenParams{RevokedAt: domain.NullMicros(&tx.Now), ID: c})
				if err != nil {
					return err
				}
				if n > 0 {
					issued = append(issued, c)
				}
			}
			next = children
		}
		ev := audit.Event{Actor: ch.Actor, TenantID: r.TenantID.String, Action: "automation_token.revoked",
			Target: audit.Target{Type: "automation_token", ID: id}}
		if len(issued) > 0 {
			ev.Details = map[string]any{"issued_tokens_revoked": issued}
		}
		_, err = svc.audit.Append(ctx, tx, ev)
		return err
	})
}
